head.script:
scwin.add = function(x, y, width, height) {
    var widget = widgetContainer1.addWidgets({
        title: "widget" + scwin.wcount,
        titleClass: "w2widget_orange",
        src: "",
        scope: true,
        x: x,
        y: y,
        unitWidth: width,
        unitHeight: height,
        params: "USER_DATA"
    });
    scwin.wcount++;
};
scwin.resize = function(widgetId, width, height) {
    var widget = widgetContainer1.resizeWidget(widgetId, width, height);
}
scwin.t1_onclick = function() {
    scwin.add(i % 4, ~~(i / 4) + 1, 1, 1);
    i++;
};
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    widgetContainer1.addWidgets({
        id: "widget0",
        title: "widget0",
        src: "",
        scope: true,
        x: 0,
        y: 0,
        unitWidth: 1,
        unitHeight: 1
    });
    widgetContainer1.addWidgets({
        id: "widget1",
        title: "widget1",
        titleClass: "w2widget_blue",
        src: null,
        scope: true,
        x: 1,
        y: 0,
        unitWidth: 1,
        unitHeight: 1
    });
    widgetContainer1.addWidgets({
        id: "widget2",
        title: "widget2",
        src: "",
        scope: true,
        x: 2,
        y: 0,
        unitWidth: 1,
        unitHeight: 1
    });
    window.scwin = {};
    scwin.wcount = 0;
    window.i = 0;
    widgetContainer1.setTitleClass("widget0", "w2widget_orange");
    widgetContainer1.removeTitleClass("widget0", "w2widget_orange");
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
